import type { H3Event } from 'nitro/h3';

// srvx >= 1 types `runtime.cloudflare.env` as `{ [key: string]: unknown }`, which does not overlap with the bindings generated by `wrangler types`, so the cast has to go through `unknown`
function getCloudflareEnv(event: H3Event): Cloudflare.Env {
	// oxlint-disable-next-line typescript/no-non-null-assertion -- We are confident that these properties will be available in the Cloudflare Workers environment
	return event.req.runtime!.cloudflare!.env as unknown as Cloudflare.Env;
}

export { getCloudflareEnv };
